window.RP_SESSION={"id":"S-4816e262d4a2","messages":[{"id":"RP-III-0110351","time":"2026-06-02T22:01:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘도 재료 준비!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110352","time":"2026-06-02T22:03:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마귀 할멈이 비 오는 날에 자주 해 주던 스튜를 준비한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110353","time":"2026-06-02T22:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"일단 도마에서 소금에 절여둔 돼지고기를 좀 꺼내서 볶기 좋은 작은 사이즈로 썰어낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110354","time":"2026-06-02T22:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"첫번째 나무 그릇에 작게 깍둑썰기 한 양파와...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110355","time":"2026-06-02T22:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110356","time":"2026-06-02T22:04:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 힘 판정 :\n[6] + [1] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0110357","time":"2026-06-02T22:05:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"손으로 마늘을 다져 누르려고 했는데...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110358","time":"2026-06-02T22:05:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"생각 해 보니 도구를 쓰는게 편하군요.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110359","time":"2026-06-02T22:05:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"칼 옆면으로 마늘을 눌러서 으깨 양파와 함께 담아 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110360","time":"2026-06-02T22:06:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"파프리카 몇 개를 잘게 썰어서 두 번째 나무 그릇에 담아 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110361","time":"2026-06-02T22:08:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"샐러리도 손가락 반 마디 정도 길이로 자르고, 당근도 씻어서 숟가락에 두 개 정도 들어갈 크기로 적당하게 깍둑썰어 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110362","time":"2026-06-02T22:08:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"파스닙은 꼭다리를 잘라내서 입 안에 넣고 씹으며 당근과 비슷한 사이즈로 자른다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110363","time":"2026-06-02T22:09:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"샐러리, 당근, 파스닙이 세 번째 나무 그릇에 들어간다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110364","time":"2026-06-02T22:10:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"감자는 껍질을 벗겨 깍둑썬 뒤 토기에 물을 넣고 잠시 담가 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110365","time":"2026-06-02T22:10:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"파슬리도 썰어서 펼쳐 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110366","time":"2026-06-02T22:11:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"토마토는 칼집을 내고 미리 물에 살짝 데쳐 껍질을 벗겨 둔다. 벗겨둔 껍질은 파스닙에 이어서 레마가 질겅질겅 씹는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110367","time":"2026-06-02T22:13:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 필살기로, 이 스튜를 만들기 위해 방금 전에 사비를 털어 푸줏간에서 사온 신선한 소고기!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110368","time":"2026-06-02T22:17:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"삼십 분 전까지만 해도 살아 있었지만 지금은 온갖 곳에 흩어져 있을 불쌍한 소의 국거리용 살점들을 도마 위에 텅, 내려놓고 손질합니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110369","time":"2026-06-02T22:22:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"냄비에 돼지 기름을 뽑아내기 위한 아주 조금의 기름을 두르고 불에 얹은 뒤, 작게 썬 돼지고기를 냄비에 부어 나무 주걱으로 저어 가며 익힌다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110370","time":"2026-06-02T22:23:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"갈색으로 색이 나고 기름이 뽑혀 나오면 양파와 마늘을 넣고 양파 겉면도 노랗게 그을릴 때, 파프리카 까지 투입.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110371","time":"2026-06-02T22:29:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"캐러웨이 씨앗, 말려서 부순 스프레딩 칠리 페퍼, 말려서 빻은 파프리카 가루를 털어넣어 향과 색을 낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110372","time":"2026-06-02T22:30:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"온갖 채소와 향신료들이 볶이면서 환상적인 향을 내는 이 때...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110373","time":"2026-06-02T22:31:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"시장에서 사온, 사후경직도 시작되지 않은 소고기를 투입!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110374","time":"2026-06-02T22:32:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110375","time":"2026-06-02T22:32:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[8] + [2] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0110376","time":"2026-06-02T22:33:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"나무 주걱으로 고기가 타지 않게 열심히 저어가며 익힌다!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110377","time":"2026-06-02T22:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수분이 날아간 냄비 바닥에 고기를 눌러 가며 잘라둔 소고기의 모든 면에서 생고기 색이 사라진다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110378","time":"2026-06-02T22:36:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그 때, 타이밍을 맞춰 데쳐둔 토마토와 물을 함께 넣는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110379","time":"2026-06-02T22:41:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"냄비 뚜껑을 닫고 잠시 익히다가 적당한 시간이 되자 손질 해 둔 샐러리, 당근, 파스닙을 냄비에 붓고 한 번 저어준 뒤, 물을 조금 더 넣는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110380","time":"2026-06-02T22:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 살짝 짭짤할 때 까지 소금을 넣고 좀 더 끓이다가, 물에 담가 둔 감자를 투입.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110381","time":"2026-06-02T22:43:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 마지막으로 파슬리를 넣고 한 번 섞은 뒤 냄비를 불에서 꺼낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110382","time":"2026-06-02T22:46:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"국자로 국물과 건더기를 적당히 건져내 그릇에 담으면...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110383","time":"2026-06-02T22:47:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맛있는 구야시 완성!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110384","time":"2026-06-02T22:52:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마침 요리를 하던 중에 추적추적. 초여름의 밤비가 내리고.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110385","time":"2026-06-02T22:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"후덥지근하던 날씨가 조금은 비에 식었을지도 모르겠다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110386","time":"2026-06-02T22:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아직 비 정도면 식을 열기에 불과한 새끼 여름 앞에서 레마는 따끈한 스튜를 숟가락으로 떠서 한 입 먹는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110387","time":"2026-06-02T23:02:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아. 향긋해.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110388","time":"2026-06-02T23:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"향긋하고, 진하고, 구수하고... 따끈해.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110389","time":"2026-06-02T23:28:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마? 뭐해?\"\n다가간다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110390","time":"2026-06-02T23:29:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아, 마침 자, 잘 왔어! \"\n\n멜리아에게도 구야시와 함께 빵을 좀 썰어서 건낸다.\n\n\" 일단 머, 먹어. 맛있을거야! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110391","time":"2026-06-02T23:30:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응? 음...\"\n레마가 만든 요리 한입 먹는다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110392","time":"2026-06-02T23:31:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"맛있는 구야시 스튜!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110393","time":"2026-06-02T23:31:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어, 어때? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110394","time":"2026-06-02T23:31:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"이거 맛있다!\"\n눈 반짝","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110395","time":"2026-06-02T23:33:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 노력한 보, 보람이 있네! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110396","time":"2026-06-02T23:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 맥주도 마, 마실래? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110397","time":"2026-06-02T23:45:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"\"뭐야. 니네 뭐 먹고있어?\"\n\n다가가서 말을 건다.","characters":["P-049655ae09cb"]},{"id":"RP-III-0110398","time":"2026-06-02T23:48:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"헤헤, 레마가 만들었어요!\"\n헤실헤실","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110399","time":"2026-06-02T23:49:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"\"나도 좀 줘. 오늘 한끼도 못먹어서 배고프네.\"\n\n자연스럽게 착석.","characters":["P-049655ae09cb"]},{"id":"RP-III-0110400","time":"2026-06-03T00:00:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아르케라스 씨도 여, 여기 드세요. \"\n\n만든 구야시와 빵, 그리고 맥주를 건내주는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110401","time":"2026-06-03T00:04:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"\"음.. 맛있네. 직접 만든거야?\"","characters":["P-049655ae09cb"]},{"id":"RP-III-0110402","time":"2026-06-03T00:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네! 재료도 최대한 시, 신선한걸 직접 사다가 마, 만들었어요! \"\n\n밝게 웃으면어 자기 그릇을 한 번 싹 비우고 또 덜어서 먹고 있다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110403","time":"2026-06-03T00:19:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"그릇을 건낸다. \n\" 나도 한 그릇만 더.. \"","characters":["P-049655ae09cb"]},{"id":"RP-III-0110404","time":"2026-06-03T00:22:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여, 여기요! \"\n\n솥에서 또 구야시를 덜어서 아르케라스에게 건낸다.\n\n\" 맥주도 더 드, 드실래요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110405","time":"2026-06-03T00:28:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"\"괜찮아. 안 마셔도돼.\"\n\n구야시를 그릇째로 마신다.\n\n\"고마워. 덕분에 잘 먹었어.\"","characters":["P-049655ae09cb"]},{"id":"RP-III-0110406","time":"2026-06-03T00:29:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 히히, 이런 나, 날씨에는 따끈하고 향긋하고 사, 살짝 매콤한게 최고죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110407","time":"2026-06-03T00:37:00+09:00","room":"RP III","name":"아르케라스","profile":"아르케라스","identity":"reviewed","type":"dialogue","body":"\"다음에도 또 해줘. 진짜 맛있더라.\"\n 말을 하곤 간다.","characters":["P-049655ae09cb"]},{"id":"RP-III-0110408","time":"2026-06-03T00:39:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 오늘도 이, 인기가 좋아서 정말 보, 보람차네요! \"\n\n기지개를 펴며 좋아하는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110409","time":"2026-06-04T18:40:00+09:00","room":"RP III","name":"카리엔","profile":"카리엔","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0110410","time":"2026-06-04T18:40:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
